  if (Math.abs(PLAYER.currentLaneX - t.lane) < 0.4 && !PLAYER.isJumping && PLAYER.onTrain !== t) {
    // 可攀爬火车(从高架跳上)
    if (t.climbable && PLAYER.isJumping && PLAYER.jumpHeight < -H() * 0.05 && slopeValue > 0.2) {
      PLAYER.onTrain = t;
      PLAYER.isJumping = false;
      PLAYER.jumpHeight = 0;
      PLAYER.vy = 0;
      PLAYER.trainRideX = 0;
    } else if (PLAYER.invincible <= 0) {
      // 被撞!
      if (PLAYER.skateboard) {
        PLAYER.skateboard = false;
        PLAYER.skateboardTimer = 0;
        spawnParticles(W() / 2, H() * PLAYER.y, 20, '#2ecc71');
      } else {
        PLAYER.hp -= 2;
        PLAYER.invincible = 1.5;
        sfxHit();
        shakeIntensity = 10;
        shakeTimer = 0.5;
        spawnParticles(W() / 2, H() * PLAYER.y, 15, '#ff0000');
        if (PLAYER.hp <= 0) {
          gameOver();
          return;
        }
      }
    }
  }
}

